async function loadSellerAvatars(client:any,profiles:Record<string,any>[]){const result:Record<string,string>={};for(const profile of profiles){const row=await client.from('seller_profile_public_avatars').select('storage_path,public_consent').eq('seller_profile_id',profile.id).maybeSingle();if(row.error||!row.data?.public_consent||!row.data.storage_path)continue;const signed=await client.storage.from('seller-profile-avatars').createSignedUrl(row.data.storage_path,3600);if(!signed.error&&signed.data?.signedUrl)result[profile.id]=signed.data.signedUrl;}return result;}
