 const sync=useCallback(async(owner:User|null,part:Page=page)=>{if(!sb||!owner){setChecking(false);return;}setLoading(true);setError('');try{if(part==='home'||part==='profile'||part==='settings'){const r=await sb.from('profiles').select('id,full_name,avatar_url').eq('id',owner.id).maybeSingle();if(r.error)throw r.error;setProfile(r.data||null);setProfileName(String(r.data?.full_name||''));}if(part==='home'||part==='business'){const r=await sb.rpc('get_my_seller_profiles');if(r.error)throw r.error;const rows=Array.isArray(r.data)?r.data:[];setSellerProfiles(rows);setSellerAvatarUrls(await loadSellerAvatars(sb,rows));}if(part==='vehicles'||part==='home')await loadVehicles(owner.id);if(part==='listings'){const result=await fetchOwnedListings(sb,owner.id);setOwnedListings(result.rows);setOwnedListingErrors(result.errors);}if(part==='vehicle'&&vehicle)await loadRecords(vehicle);if(part==='orders'){const result=await loadCustomerOrders(sb);setOrders(result);}if(part==='wallet'){const result=await sb.rpc('austa_get_my_wallet_statement');if(result.error)throw result.error;const row=Array.isArray(result.data)?result.data[0]:result.data;setWallet(row?{...row,ledger:Array.isArray(row.ledger)?row.ledger:[]}:null);}if(part==='reminders'&&vehicle)await loadRecords(vehicle);}catch(e){setError(failText(e));}finally{setLoading(false);setChecking(false);setRefreshing(false);}},[sb,page,vehicle,loadVehicles,loadRecords]);
