 const authenticate=async()=>{if(!sb)return setAuthError('Supabase konfiqurasiyası yoxdur.');setAuthBusy(true);setAuthError('');setNotice('');try{if(authMode==='reset'){const r=await sb.auth.resetPasswordForEmail(email.trim());if(r.error)throw r.error;setNotice('Şifrəni bərpa etmək üçün e-poçt göndərildi.');return;}const r=authMode==='signin'?await sb.auth.signInWithPassword({email:email.trim(),password}):await sb.auth.signUp({email:email.trim(),password});if(r.error)throw r.error;if(authMode==='signup'&&!r.data.session){setNotice('Hesabı aktivləşdirmək üçün e-poçtunuza göndərilən təsdiq keçidini açın.');setAuthMode('signin');}else if(r.data.user)setUser(r.data.user);}catch(e){setAuthError(failText(e));}finally{setAuthBusy(false);}};
 const normalizeAzPhone=normalizeAzerbaijaniPhone;
 useEffect(()=>{let active=true;const base=process.env.EXPO_PUBLIC_SUPABASE_URL?.trim().replace(/\/$/,'');if(!base)return;const refresh=()=>{void fetch(`${base}/functions/v1/whatsapp-send-sms`,{headers:{accept:'application/json'}}).then(response=>response.ok?response.json():null).then(result=>{if(!active)return;const enabled=result?.enabled===true;setPhoneAuthEnabled(enabled);if(!enabled){setPhoneFlow(false);setPhoneOtpSent(false);setOtp('');}}).catch(()=>{if(active){setPhoneAuthEnabled(false);setPhoneFlow(false);setPhoneOtpSent(false);setOtp('');}});};refresh();const timer=setInterval(refresh,30000);return()=>{active=false;clearInterval(timer);};},[]);
 useEffect(()=>{if(phoneOtpCooldown<=0)return;const timer=setTimeout(()=>setPhoneOtpCooldown(value=>Math.max(0,value-1)),1000);return()=>clearTimeout(timer);},[phoneOtpCooldown]);
 const sendPhoneCode=async(linkCurrentAccount=false)=>{if(!phoneAuthEnabled)return setAuthError('Telefonla giriş hazırda aktiv deyil. E-poçt və şifrə ilə daxil olun.');if(!sb)return setAuthError('Supabase konfiqurasiyası yoxdur.');if(phoneOtpCooldown>0)return setAuthError(`Təkrar kod istəmək üçün ${phoneOtpCooldown} saniyə gözləyin.`);const normalized=normalizeAzPhone(phone);if(!normalized)return setAuthError('Azərbaycan mobil nömrəsini düzgün daxil edin. Məsələn: 0103999217.');setAuthBusy(true);setAuthError('');setNotice('');try{if(linkCurrentAccount){if(!user)throw new Error('Telefonu bağlamaq üçün əvvəlcə mövcud hesabınıza daxil olun.');const r=await sb.auth.updateUser({phone:normalized});if(r.error)throw r.error;}else{const r=await sb.auth.signInWithOtp({phone:normalized,options:{channel:'sms',shouldCreateUser:authMode==='signup',...(authMode==='signup'?{data:{austa_role:'customer',phone_verified:false,account_status:'active'}}:{})}});if(r.error)throw r.error;}setPhone(normalized);setPhoneOtpSent(true);setPhoneOtpCooldown(60);setNotice('Kod sorğusu qəbul edildi. WhatsApp-da gələn 6 rəqəmli kodu daxil edin.');}catch(e){setAuthError(failText(e));}finally{setAuthBusy(false);}};
 const verifyPhoneCode=async(linkCurrentAccount=false)=>{if(!sb)return setAuthError('Supabase konfiqurasiyası yoxdur.');const normalized=normalizeAzPhone(phone);if(!normalized||!/^\d{6}$/.test(otp.trim()))return setAuthError('Düzgün nömrə və 6 rəqəmli kod daxil edin.');setAuthBusy(true);setAuthError('');setNotice('');try{const r=await sb.auth.verifyOtp({phone:normalized,token:otp.trim(),type:linkCurrentAccount?'phone_change':'sms'});if(r.error)throw r.error;if(!r.data.user)throw new Error('Supabase Auth istifadəçi sessiyası qaytarmadı.');setPhoneOtpSent(false);setOtp('');setUser(r.data.user);setPhoneFlow(false);setNotice(linkCurrentAccount?'Telefon nömrəsi bu hesabla təsdiqləndi.':'Telefon təsdiqləndi və hesab sessiyası açıldı.');}catch(e){setAuthError(failText(e));}finally{setAuthBusy(false);}};
