 const toggleSellerAvatar=async(seller:Record<string,any>,share:boolean)=>{if(!sb||!user)return;setBusy(true);setError('');try{const path=`${user.id}/${seller.id}/avatar.jpg`;if(share){const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted)throw new Error('Avatar seçmək üçün foto kitabxanası icazəsi verilmədi.');const selected=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:true,aspect:[1,1],quality:1});if(selected.canceled||!selected.assets[0])return;const optimized=await ImageManipulator.manipulateAsync(selected.assets[0].uri,[{resize:{width:512,height:512}}],{compress:.82,format:ImageManipulator.SaveFormat.JPEG});const local=new File(optimized.uri);if(!local.exists||!local.size||local.size>2*1024*1024)throw new Error('Avatar şəkli 2 MiB həddindən kiçik olmalıdır.');const bytes=await local.bytes();if(bytes[0]!==0xff||bytes[1]!==0xd8||bytes[2]!==0xff)throw new Error('Avatar JPEG formatında olmalıdır.');const saved=await sb.from('seller_profile_public_avatars').upsert({seller_profile_id:seller.id,owner_id:user.id,storage_path:path,public_consent:true,consented_at:new Date().toISOString(),updated_at:new Date().toISOString()},{onConflict:'seller_profile_id'});if(saved.error)throw saved.error;const uploaded=await sb.storage.from('seller-profile-avatars').upload(path,bytes,{contentType:'image/jpeg',upsert:true,cacheControl:'3600'});if(uploaded.error){await sb.from('seller_profile_public_avatars').update({public_consent:false,consented_at:null}).eq('seller_profile_id',seller.id).eq('owner_id',user.id);throw uploaded.error;}const signed=await sb.storage.from('seller-profile-avatars').createSignedUrl(path,3600);if(signed.error||!signed.data?.signedUrl)throw signed.error||new Error('Avatar yükləndi, amma önizləmə linki təsdiqlənmədi.');setSellerAvatarUrls(current=>({...current,[seller.id]:signed.data.signedUrl}));}else{const current=await sb.from('seller_profile_public_avatars').select('storage_path').eq('seller_profile_id',seller.id).eq('owner_id',user.id).maybeSingle();if(current.error)throw current.error;if(current.data?.storage_path){const hidden=await sb.from('seller_profile_public_avatars').update({public_consent:false,consented_at:null,updated_at:new Date().toISOString()}).eq('seller_profile_id',seller.id).eq('owner_id',user.id);if(hidden.error)throw hidden.error;const removed=await sb.storage.from('seller-profile-avatars').remove([current.data.storage_path]);if(removed.error)throw removed.error;}setSellerAvatarUrls(current=>{const next={...current};delete next[seller.id];return next;});}}catch(e){setError(failText(e));}finally{setBusy(false);}};
