 const saveVehicle=async()=>{if(!sb||!user)return;setBusy(true);setError('');try{const year=Number(form.year),mileage=Number(form.mileage);if(!form.make?.trim()||!form.model?.trim()||!form.plate_number?.trim()||!Number.isInteger(year)||year<1886||year>2100||!Number.isInteger(mileage)||mileage<0)throw new Error('Marka, model, il, dövlət nişanı və düzgün yürüş daxil edin.');const vin=form.vin.trim().toUpperCase();if(vin&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin))throw new Error('VIN 17 uyğun hərf və rəqəmdən ibarət olmalıdır.');const payload={make:form.make.trim(),model:form.model.trim(),year,plate_number:form.plate_number.trim().toUpperCase(),vin:vin||null,mileage,engine:form.engine.trim()||null,fuel_type:form.fuel_type.trim()||null,transmission:form.transmission.trim()||null,color:form.color.trim()||null,notes:form.notes.trim()};const q=vehicle?sb.from('vehicles').update(payload).eq('id',vehicle.id).eq('user_id',user.id):sb.from('vehicles').insert({...payload,user_id:user.id});const r=await q.select(VEHICLE_FIELDS).single();if(r.error)throw r.error;setFormVisible(false);await loadVehicles(user.id);if(vehicle)setVehicle(r.data as Vehicle);setNotice('Avtomobil məlumatları saxlanıldı.');}catch(e){setError(failText(e));}finally{setBusy(false);}};
